test('Tapping the circle packs and unpacks with Undo while preserving saved data',()=>{run("items=[{id:'t1',name:'Stove',place:'dry10',category:'Kitchen',status:'check',qty:2,note:'Keep',spot:'S4',photo:'data:image/jpeg;base64,YWJj'}]");assert(run("togglePacked('t1')"));assert.equal(run('items[0].status'),'packed');assert.equal(run('items[0].qty'),2);run('undoAction()');assert.equal(run('items[0].status'),'check');assert(run("togglePacked('t1')"));assert(run("togglePacked('t1')"));assert.equal(run('items[0].status'),'stock');assert.equal(run('items[0].qty'),2);assert.equal(run('items[0].note'),'Keep');assert.equal(run('items[0].photo'),originalPhoto);assert.equal(run('items[0].spot'),'S4');run("items[0].qty=0;items[0].lastNonzeroQty=3");assert(run("togglePacked('t1')"));assert.equal(run('items[0].status'),'packed');assert.equal(run('items[0].qty'),3);run("items[0].archived=true");assert.equal(run("togglePacked('t1')"),false);run("items[0].archived=false")});
test('Legacy stored statuses stay readable without a verify state',()=>{run("items=[{id:'v1',name:'Old verify item',place:'waist',category:'Safety',status:'check',qty:1}];persist();filterKit('')");const h=elements.get('inventoryItems').innerHTML;assert(h.includes('aria-label="Owned gear"'));run('renderDetail("waist")');assert(elements.get('detailItems').innerHTML.includes('aria-label="To pack"'));assert(!/verify/i.test(h.replaceAll('Old verify item','')));assert.equal(JSON.parse(storage.get('fieldkit_inventory_v1')).items[0].status,'check');elements.get('statusFilter').value='unpacked';run('renderInventory()');assert(elements.get('inventoryItems').innerHTML.includes('Old verify item'));elements.get('statusFilter').value='packed';run('renderInventory()');assert(!elements.get('inventoryItems').innerHTML.includes('Old verify item'));elements.get('statusFilter').value=''});
test('Editing a saved verify item keeps its status unless the user changes it',()=>{run("quickOpen(null,'v1')");assert.equal(elements.get('quickStatus').value,'stock');elements.get('quickName').value='Old verify item renamed';run('quickSave({preventDefault(){}})');assert.equal(run('items[0].status'),'check');assert.equal(run('items[0].name'),'Old verify item renamed');run("quickOpen(null,'v1')");elements.get('quickStatus').value='packed';run('quickSave({preventDefault(){}})');assert.equal(run('items[0].status'),'packed')});
test('Edit sheet Move button opens the accessible move menu',()=>{run("quickOpen(null,'v1')");elements.get('quickMove').onclick();assert(!elements.get('moveLayer').classList.contains('hidden'));assert.equal(run('moveTarget'),'v1');run('closeMove()')});
test('Empty search shows a clear message instead of a blank list',()=>{elements.get('search').value='zzzz-no-match';run('renderInventory()');assert(elements.get('inventoryItems').innerHTML.includes('No gear matches.'));elements.get('search').value='';run('renderInventory()')});

test('Built-in finder cuts separate items out of a plain background',()=>{const w=120,h=80,a=new Uint8ClampedArray(w*h*4);for(let i=0;i<w*h;i++){a[i*4]=200+(i%3);a[i*4+1]=190;a[i*4+2]=170;a[i*4+3]=255}const fill=(x0,y0,x1,y1,c)=>{for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){const k=(y*w+x)*4;a[k]=c[0];a[k+1]=c[1];a[k+2]=c[2]}};fill(10,10,30,25,[30,30,30]);fill(60,12,75,40,[40,110,170]);fill(20,50,50,70,[200,30,30]);context.__a=a;const b=run('scanSegment(__a,120,80)');assert.equal(b.length,3);const near=(box,x,y)=>Math.abs(box[0]-x)<=3&&Math.abs(box[1]-y)<=3;assert(b.some(x=>near(x,10,10)));assert(b.some(x=>near(x,60,12)));assert(b.some(x=>near(x,20,50)))});
test('Built-in names come from matching detections; background classes are ignored',()=>{context.__seg=[[10,10,20,15],[60,12,15,28]];context.__det=[{class:'cup',score:.9,bbox:[11,11,18,14]},{class:'dining table',score:.9,bbox:[0,0,120,80]},{class:'bottle',score:.8,bbox:[90,50,10,20]},{class:'knife',score:.4,bbox:[100,5,5,5]}];const r=run('scanCombine(__seg,__det)');assert.equal(r.length,3);assert.equal(r[0].name,'Cup');assert.equal(r[0].category,'Kitchen');assert.equal(r[1].name,'');assert.equal(r[2].name,'Water bottle')});
test('Gemini answers become named pieces with pixel boxes',()=>{context.__resp={candidates:[{content:{parts:[{text:'```json\n[{"name":"Headlamp","category":"Light & power","count":2,"box_2d":[100,200,300,500]},{"name":"","count":1},{"name":"Mystery thing","category":"Nonsense","count":0,"box_2d":[5,5,1,1]}]\n```'}]}}]};const r=run('scanParseGemini(__resp,1000,500)');assert.equal(r.length,2);assert.deepEqual(r[0],{name:'Headlamp',category:'Light & power',count:2,box:[200,50,300,100]});assert.equal(r[1].category,'Other');assert.equal(r[1].count,1);assert.equal(r[1].box,null);assert.throws(()=>run('scanParseGemini({candidates:[]},10,10)'))});
test('Smart scan picks the best free flash model the key can use',()=>{context.__models=[{name:'models/gemini-2.5-flash',supportedGenerationMethods:['generateContent']},{name:'models/gemini-3.8-flash',supportedGenerationMethods:['generateContent']},{name:'models/gemini-3.8-flash-lite',supportedGenerationMethods:['generateContent']},{name:'models/gemini-3.8-flash-image',supportedGenerationMethods:['generateContent']},{name:'models/gemini-4-flash-preview',supportedGenerationMethods:['generateContent']},{name:'models/text-embedding',supportedGenerationMethods:['embedContent']}];assert.equal(run('scanPickModel(__models)'),'gemini-3.8-flash');assert.equal(run('scanPickModel([])'),'gemini-2.5-flash')});
test('Scan pieces merge duplicate names and number unnamed items',()=>{const p=run("scanMakePieces([{name:'Batteries',category:'Light & power',count:2,box:null},{name:'batteries ',count:3},{name:''},{name:''},{name:'Compass',category:'Safety'}])");assert.equal(p.length,4);assert.equal(p[0].count,5);assert.equal(p[0].emoji,'🔋');assert.equal(p[1].name,'Item 1');assert.equal(p[2].name,'Item 2');assert.equal(p[3].emoji,'🧭')});
test('Saving a scan updates matching gear, adds new gear and touches nothing else',()=>{run("storageBlocked=false;items=[{id:'h1',name:'Headlamp',place:'waist',category:'Light & power',status:'check',qty:1,note:'Keep note',spot:'Pocket',photo:''},{id:'o1',name:'Headlamp',place:'dry10',category:'Light & power',status:'packed',qty:4,photo:''},{id:'a1',name:'Whistle',place:'waist',status:'stock',qty:0,archived:true},{id:'p1',name:'Map',place:'waist',category:'Safety',status:'packed',qty:1,photo:'data:image/jpeg;base64,b2xk'}];persist()");const other=run("JSON.stringify(items.filter(i=>i.id==='o1'||i.id==='a1'))");const r=run("scanApply('waist',[{name:'headlamp',category:'Light & power',count:3,inBag:true,crop:'data:image/jpeg;base64,bmV3'},{name:'Map',count:1,inBag:false,crop:'data:image/jpeg;base64,eA=='},{name:'Whistle',category:'Safety',count:1,inBag:true,crop:''},{name:'Water bottle',category:'Water & food',count:1,inBag:false,crop:''},{name:'water bottle',count:1,inBag:true,crop:''},{name:'  ',count:1}])");assert.deepEqual(JSON.parse(JSON.stringify(r)),{added:2,updated:2,packed:2});const h=run("items.find(i=>i.id==='h1')");assert.equal(h.qty,3);assert.equal(h.status,'packed');assert.equal(h.note,'Keep note');assert.equal(h.spot,'Pocket');assert.equal(h.photo,'data:image/jpeg;base64,bmV3');const m=run("items.find(i=>i.id==='p1')");assert.equal(m.status,'stock');assert.equal(m.photo,'data:image/jpeg;base64,b2xk');assert.equal(run("JSON.stringify(items.filter(i=>i.id==='o1'||i.id==='a1'))"),other);const w=run("items.find(i=>i.name==='Whistle'&&!i.archived)");assert.equal(w.place,'waist');assert.equal(w.status,'packed');assert.equal(w.source,'scan');const b=run("items.find(i=>i.name==='Water bottle')");assert.equal(b.qty,2);assert.equal(b.status,'stock');assert.throws(()=>run("scanApply('__proto__',[{name:'x'}])"))});
test('Scan save keeps a recovery snapshot and Undo restores the inventory exactly',()=>{run("items=[{id:'u1',name:'Stove',place:'dry10',category:'Kitchen',status:'stock',qty:1,photo:''}];persist()");const before=storage.get('fieldkit_inventory_v1');const beforeItems=run('JSON.stringify(items)');run("scanOpen('dry10');scanState={kit:'dry10',pieces:[{name:'Stove',count:2,inBag:true,crop:''},{name:'Fuel canister',category:'Fire & fuel',count:1,inBag:false,crop:''}]};scanSave()");assert.equal(storage.get('fieldkit_recovery_v1'),before);assert.equal(run('items.length'),2);assert.equal(run("items.find(i=>i.id==='u1').qty"),2);assert.equal(run('scanState'),null);assert(elements.get('toastText').textContent.includes('1 added, 1 updated'));run('undoAction()');assert.equal(run('JSON.stringify(items)'),beforeItems);assert.equal(JSON.parse(storage.get('fieldkit_inventory_v1')).items.length,1)});
test('Smart scan key is validated, kept on the device and never exported',()=>{elements.get('geminiKey').value='short';elements.get('geminiKeyForm').onsubmit({preventDefault(){}});assert.equal(storage.get('fieldkit_gemini_key_v1'),undefined);elements.get('geminiKey').value='AIzaSyTESTkey_1234567890abcdefXYZ';elements.get('geminiKeyForm').onsubmit({preventDefault(){}});assert.equal(storage.get('fieldkit_gemini_key_v1'),'AIzaSyTESTkey_1234567890abcdefXYZ');assert.equal(elements.get('geminiKey').value,'');assert(!run('toJson()').includes('AIzaSy'));elements.get('geminiKeyRemove').onclick();assert.equal(storage.get('fieldkit_gemini_key_v1'),undefined)});
test('Smart scan can be turned on from the Scan screen itself',()=>{run("scanOpen('waist')");assert.equal(elements.get('scanKeyToggle').textContent,'✨ Turn on Smart scan (free)');elements.get('scanKeyInput').value='bad key';elements.get('scanKeyForm').onsubmit({preventDefault(){}});assert(elements.get('scanKeyStatus').textContent.includes('does not look'));assert.equal(storage.get('fieldkit_gemini_key_v1'),undefined);elements.get('scanKeyInput').value='AIzaSyTESTkey_1234567890abcdefXYZ';elements.get('scanKeyForm').onsubmit({preventDefault(){}});assert.equal(storage.get('fieldkit_gemini_key_v1'),'AIzaSyTESTkey_1234567890abcdefXYZ');assert.equal(elements.get('scanKeyInput').value,'');assert.equal(elements.get('scanEngine').textContent,'Smart scan');assert(elements.get('scanKeyToggle').textContent.includes('Smart scan is on'));elements.get('geminiKeyRemove').onclick();run('scanClose(true)')});
test('Keys in newer Google formats are accepted; spaces and quotes from copying are removed',()=>{assert.equal(run("scanSaveKey(' \"AQ.Ab8RN6Ltest-key_with.dots/and+more12345\" \\n')"),'');assert.equal(storage.get('fieldkit_gemini_key_v1'),'AQ.Ab8RN6Ltest-key_with.dots/and+more12345');assert(run("scanSaveKey('too short')").length>0);assert(run("scanSaveKey('')").length>0);storage.delete('fieldkit_gemini_key_v1')});

test('Select mode picks several items and Select all follows the visible list',()=>{run("items=[{id:'b1',name:'Lamp',place:'waist',category:'Light & power',status:'stock',qty:2,note:'n1',photo:''},{id:'b2',name:'Map',place:'waist',category:'Safety',status:'check',qty:0,lastNonzeroQty:3,photo:''},{id:'b3',name:'Tarp',place:'dry10',category:'Clothing & shelter',status:'packed',qty:1,photo:''},{id:'b4',name:'Old cup',place:'shared',status:'stock',qty:0,archived:true,photo:''}];persist();openZone=null;inventoryView='active';refillOnly=false;filterKit('waist');setSelectMode(true)");assert(context.document.body.classList.contains('select-mode'));assert(!elements.get('bulkBar').classList.contains('hidden'));assert.equal(elements.get('selectToggle').textContent,'Done');const h=elements.get('inventoryItems').innerHTML;assert(h.includes('data-select="b1"'));assert(!h.includes('data-move="b1"'));run("toggleSelect('b1')");assert.equal(elements.get('bulkCount').textContent,'1 selected');run('selectAllToggle()');assert.deepEqual(run('[...selected].sort()'),['b1','b2']);assert.equal(elements.get('bulkAll').textContent,'Deselect all');run('selectAllToggle()');assert.equal(run('selected.size'),0);run('setSelectMode(false)');assert(elements.get('bulkBar').classList.contains('hidden'))});
test('Bulk pack, +1, −1, empty and move change only the selected items, with one Undo',()=>{const before=run('JSON.stringify(items)');run("filterKit('');setSelectMode(true);toggleSelect('b1');toggleSelect('b2')");assert.equal(run("bulkApply('pack')"),2);assert.equal(run('selectMode'),false);assert.equal(run("items.find(i=>i.id==='b2').qty"),3);assert.equal(run("items.find(i=>i.id==='b2').status"),'packed');assert.equal(run("items.find(i=>i.id==='b1').note"),'n1');assert.equal(run("items.find(i=>i.id==='b3').status"),'packed');assert(elements.get('toastText').textContent.includes('2 items packed'));run('undoAction()');assert.equal(run('JSON.stringify(items)'),before);
 run("setSelectMode(true);toggleSelect('b1');toggleSelect('b3')");assert.equal(run("bulkApply('plus')"),2);assert.equal(run("items.find(i=>i.id==='b1').qty"),3);assert.equal(run("items.find(i=>i.id==='b3').qty"),2);
 run("setSelectMode(true);toggleSelect('b3')");run("bulkApply('minus')");run("setSelectMode(true);toggleSelect('b3')");run("bulkApply('minus')");assert.equal(run("items.find(i=>i.id==='b3').qty"),0);assert.equal(run("items.find(i=>i.id==='b3').archived"),undefined);assert.equal(run("items.find(i=>i.id==='b3').lastNonzeroQty"),1);
 run("setSelectMode(true);toggleSelect('b1')");run("bulkApply('empty')");assert.equal(run("items.find(i=>i.id==='b1').qty"),0);assert.equal(run("items.find(i=>i.id==='b1').lastNonzeroQty"),3);
 run("setSelectMode(true);toggleSelect('b1');toggleSelect('b2')");assert.equal(run("bulkApply('move','evac')"),2);assert.equal(run("items.find(i=>i.id==='b1').place"),'evac');assert.equal(run("bulkApply('move','__proto__')"),0);
 run("setSelectMode(true);toggleSelect('b1');toggleSelect('b2')");assert.equal(run("bulkApply('unpack')"),2);assert.equal(run("items.find(i=>i.id==='b2').status"),'check');assert.equal(run("itemMoveState(items.find(i=>i.id==='b2'))"),'unpacked');assert.equal(run("items.find(i=>i.id==='b1').qty"),3)});
test('Bulk archive, restore and confirmed permanent delete follow the Archive rules',()=>{run("setSelectMode(true);toggleSelect('b1');toggleSelect('b2')");assert.equal(run("bulkApply('archive')"),2);assert(run("items.find(i=>i.id==='b1').archived"));run("inventoryView='archived';renderInventory();setSelectMode(true)");assert(elements.get('bulkActions').innerHTML.includes('data-bulk="delete"'));assert(!elements.get('bulkActions').innerHTML.includes('data-bulk="pack"'));run("toggleSelect('b1')");assert.equal(run("bulkApply('restore')"),1);assert.equal(run("items.find(i=>i.id==='b1').archived"),false);run("setSelectMode(true);toggleSelect('b2');toggleSelect('b4')");context.confirm=()=>false;assert.equal(run("bulkApply('delete')"),0);assert.equal(run('items.length'),4);context.confirm=()=>true;assert.equal(run("bulkApply('delete')"),2);assert.equal(run('items.length'),2);run('load()');assert.equal(run('items.length'),2);run("setSelectMode(true);toggleSelect('b1')");assert.equal(run("bulkApply('delete')"),0);assert.equal(run('items.length'),2);run("setSelectMode(false);inventoryView='active';renderInventory()")});
test('Select mode turns off when changing screens and blocks swipe gestures',()=>{run("setSelectMode(true)");run("tabShow('bags')");assert.equal(run('selectMode'),false);run("tabShow('inventory');setSelectMode(true);zoneOpen('waist')");assert.equal(run('selectMode'),false);run('zoneClose()')});

test('Trip descriptions parse days, people, destination and editable trip style',()=>{const x=JSON.parse(run("JSON.stringify(parseTrip('3 day trip to San Diego for 3 people'))"));assert.deepEqual(x,{destination:'San Diego',days:3,people:3,style:'beach'});assert.equal(run("parseTrip('two nights camping for four people').days"),3);assert.equal(run("parseTrip('two nights camping for four people').people"),4);assert.equal(run("parseTrip('winter trip for 99 people').people"),12)});
test('Recommendations separate per-person items and shared quantities',()=>{run("tripDraft=recommendTrip(parseTrip('3 day trip to San Diego for 3 people'))");assert.equal(run('tripDraft.packs.length'),4);assert.equal(run('tripDraft.packs[0].items.find(i=>i.name==="Daily outfits").qty'),3);assert.equal(run('tripDraft.packs[3].items.find(i=>i.name==="Reusable water bottle").qty'),3);assert(run('tripDraft.packs[0].items.some(i=>i.name==="Swimwear")'));assert.equal(run("recommendTrip(parseTrip('camping for 2 people')).packs.length"),4)});
test('Local trip plans reference owned stock and never add suggested inventory',()=>{run("tripPlans=[];items=[{id:'lamp',name:'Headlamp',place:'shared',category:'Light & power',status:'stock',qty:2,weightG:100,note:'mine',photo:''},{id:'snack',name:'Day snack portions',place:'shared',category:'Water & food',status:'stock',qty:2,weightG:40},{id:'protected',name:'Rain layer',place:'evac',category:'Clothing & shelter',status:'stock',qty:1},{id:'zero',name:'Trail shoes',place:'shared',status:'stock',category:'Clothing & shelter',qty:0},{id:'suggested',name:'Sun hat',place:'shared',status:'stock',category:'Clothing & shelter',qty:3,source:'trip-plan'}];persist();tripDraft=planLocal({destination:'Gila',days:3,people:2,style:'hike',when:'Nov',extra:''})");const before=run('JSON.stringify(items)');assert(run('planSave(tripDraft)'));assert.equal(run('JSON.stringify(items)'),before);assert.equal(run('tripDraft.items.find(r=>r.inventoryId==="lamp").quantity'),2);assert.equal(run('tripDraft.items.find(r=>r.inventoryId==="snack").quantity'),2);assert.equal(run('tripDraft.missing.find(m=>m.inventoryId==="snack").quantity'),4);assert(!run('tripDraft.items.some(r=>["protected","zero","suggested"].includes(r.inventoryId))'));assert.equal(run('tripPlans.length'),1)});
test('Trip packing supports full toggle, partial quantities, weights and independent inventory',()=>{run('plannerOpen(tripPlans[0].id)');assert(run('planSetPacked("lamp",1)'));assert.equal(run('planCurrent().items.find(r=>r.inventoryId==="lamp").packed'),1);assert(elements.get('plannerPacks').innerHTML.includes('partial'));assert.equal(run('planWeight(planCurrent()).packed'),100);run('planSetPacked("lamp",99)');assert.equal(run('planCurrent().items.find(r=>r.inventoryId==="lamp").packed'),2);assert.equal(run('items.find(i=>i.id==="lamp").status'),'stock');run('planSetPacked("lamp",0)');assert.equal(run('planWeight(planCurrent()).packed'),0)});
test('AI validation rejects unknown or duplicate inventory and caps stock with shortfalls',()=>{assert.throws(()=>run('planNormalize({items:[{inventoryId:"alien",quantity:1}],missing:[]},planCurrent().spec)'));assert.throws(()=>run('planNormalize({items:[{inventoryId:"lamp",quantity:1},{inventoryId:"lamp",quantity:1}],missing:[]},planCurrent().spec)'));assert.equal(run('planNormalize({items:[{inventoryId:"lamp",quantity:4}],missing:[]},planCurrent().spec).items[0].quantity'),2);assert.equal(run('planNormalize({items:[{inventoryId:"lamp",quantity:4}],missing:[]},planCurrent().spec).missing[0].quantity'),2)});
test('Optimization preserves manual edits, packed gear, and exclusions',()=>{run('planMutate(p=>{p.items.find(r=>r.inventoryId==="lamp").locked=true;p.excluded=["protected"]});planSetPacked("snack",1)');assert.equal(run('planNormalize({items:[],missing:[]},planCurrent().spec,planCurrent()).items.length'),2);assert.equal(run('planNormalize({items:[],missing:[]},planCurrent().spec,planCurrent()).items.find(r=>r.inventoryId==="snack").packed'),1)});
test('Snap preview flags ambiguous matches and repeat photos do not double count',()=>{assert.equal(run('planSnapNormalize({matches:[{inventoryId:"alien",label:"thing",visibleQuantity:1,uncertain:false}]},planCurrent())[0].uncertain'),true);run('planSnapApply([{inventoryId:"lamp",visibleQuantity:1}]);planSnapApply([{inventoryId:"lamp",visibleQuantity:1}])');assert.equal(run('planCurrent().items.find(r=>r.inventoryId==="lamp").packed'),1);run('planSnapApply([{inventoryId:"lamp",visibleQuantity:9}])');assert.equal(run('planCurrent().items.find(r=>r.inventoryId==="lamp").packed'),2)});
test('New trips warn of gear packed for another active trip',()=>{run('window.firstPlan=planClone(planCurrent());tripDraft=planLocal(planCurrent().spec);tripDraft.id="plan_second";planSave(tripDraft)');assert.equal(run('planOverlap(planCurrent(),planCurrent().items.find(r=>r.inventoryId==="lamp")).length'),1)});
test('Acquired shortfalls add only obtained quantity, keep remaining missing, and preserve storage',()=>{run('window.missingIndex=planCurrent().missing.findIndex(m=>m.inventoryId==="snack")');assert(run('planAcquireSave(window.missingIndex,1,"shared","S4")'));assert.equal(run('items.find(i=>i.id==="snack").qty'),3);assert.equal(run('planCurrent().items.find(r=>r.inventoryId==="snack").quantity'),3);assert.equal(run('planCurrent().missing.find(m=>m.inventoryId==="snack").quantity'),3);assert.equal(run('items.find(i=>i.id==="snack").spot'),'S4')});
test('Trips persist in backups, reload and import without changing reset marker',()=>{const backup=run('toJson()');assert.equal(JSON.parse(backup).tripPlans.length,2);run('load()');assert.equal(run('tripPlans.length'),2);assert(run('replaceInventory(JSON.parse(toJson()))'));assert.equal(run('tripPlans.length'),2);assert.equal(storage.get('fieldkit_empty_start_2026_v1'),'1');assert.throws(()=>run('validatedTripPlans([{id:"__proto__",items:[],missing:[],spec:{}}])'))});
