test('Hold-to-drag waits for the hold, reorders on drop, and cancels without stock changes',()=>{run('selectMode=false');const timer=context.setTimeout,clear=context.clearTimeout;let hold=null;context.setTimeout=(fn,ms)=>{if(ms===320)hold=fn;return 77};context.clearTimeout=id=>{if(id===77)hold=null};const row=element('dragRow'),grip=element('grip'),target=element('target');row.dataset={entityKind:'gear',entityId:'g_c'};target.dataset={entityKind:'gear',entityId:'g_b'};target.closest=q=>q==='[data-entity-kind][data-entity-id]'||q==='[data-drop-zone],[data-assign-person],[data-entity-kind]'?target:null;grip.dataset={dragKind:'gear',dragId:'g_c'};grip.closest=q=>q==='[data-drag-kind]'?grip:q==='[data-entity-kind][data-entity-id]'?row:null;grip.setPointerCapture=()=>{};grip.hasPointerCapture=()=>false;context.document.elementFromPoint=()=>target;const fire=(type,x,y)=>{const e={target:grip,button:0,isPrimary:true,pointerId:90,clientX:x,clientY:y,preventDefault(){}};for(const fn of events[type]||[])fn(e)};const stock=run('items.reduce((n,i)=>n+i.qty,0)');fire('pointerdown',180,300);assert.equal(run('touchDrag'),null);assert(hold);hold();assert(run('touchDrag!==null'));fire('pointermove',170,200);assert(target.classList.contains('entity-insert-before'));assert(elements.get('entityGhost').textContent.includes('Before '));fire('pointerup',170,200);assert(!target.classList.contains('entity-insert-before'));assert(!target.attributes['data-drop-label']);assert.equal(run('touchDrag'),null);assert(run('items.findIndex(i=>i.id==="g_c")<items.findIndex(i=>i.id==="g_b")'));assert.equal(run('items.reduce((n,i)=>n+i.qty,0)'),stock);const before=run('JSON.stringify(items)');fire('pointerdown',180,300);fire('pointercancel',180,300);assert.equal(hold,null);assert.equal(run('touchDrag'),null);assert.equal(run('JSON.stringify(items)'),before);context.setTimeout=timer;context.clearTimeout=clear});
