// Dispatch capture listeners before bubbling listeners, with real cancellation semantics.
function gestureEvent(type,target,x=180,y=300,pointerId=201,extras={}){const e={type,target,clientX:x,clientY:y,pointerId,button:0,isPrimary:true,detail:1,cancelable:true,prevented:false,stopped:false,preventDefault(){this.prevented=true},stopImmediatePropagation(){this.stopped=true},...extras};const listeners=[...(eventOrder[type]||[])].sort((a,b)=>Number(b.capture)-Number(a.capture));for(const {handler}of listeners){handler(e);if(e.stopped)break}return e}
function swipeFixture(kind,id){const row=element('swipeFixture'),surface=element('swipeSurface'),leading=element('leading'),trailing=element('trailing');row.dataset={entityKind:kind,entityId:id};leading.dataset.swipeRail='leading';trailing.dataset.swipeRail='trailing';leading.inert=trailing.inert=true;row.querySelector=()=>surface;row.querySelectorAll=()=>[leading,trailing];row.closest=q=>q==='[data-entity-kind][data-entity-id]'?row:null;row.setPointerCapture=p=>row.captured=p;row.hasPointerCapture=p=>row.captured===p;row.releasePointerCapture=p=>{row.captured=null;gestureEvent('lostpointercapture',row,180,300,p)};const content=element('swipeContent');content.closest=q=>q==='[data-entity-kind][data-entity-id]'?row:null;return {row,surface,leading,trailing,content,swipe(dx,dy=2){gestureEvent('pointerdown',content);gestureEvent('pointermove',content,180+dx,300+dy);gestureEvent('pointerup',content,180+dx,300+dy)},action(name){const b=element('action');b.dataset.swipeAction=name;b.closest=q=>q==='[data-swipe-action]'?b:q==='[data-entity-kind][data-entity-id]'?row:null;return b}}}
test('Swipe scenarios use disposable stock and a saved trip',()=>{run('resetEntityGesture();quickClose();closeQty();zoneClose();plannerClose();selectMode=false;current="inventory";openZone=null;inventoryView="active";items=[{id:"sw_1",name:"Test lamp",place:"shared",status:"stock",qty:3,weightG:100,photo:"data:image/jpeg;base64,eA==",note:"keep"},{id:"sw_2",name:"Map",place:"shared",status:"stock",qty:1},{id:"sw_zero",name:"Empty stock",place:"shared",status:"stock",qty:0},{id:"sw_archive",name:"Archived stock",place:"shared",status:"stock",qty:0,archived:true}];tripPlans=[];plannerTripId=null;tripDraft=null;entityContext=null;persist();tripDraft=planNormalize({name:"Gesture trip",items:[{inventoryId:"sw_1",quantity:3,reason:"Light",person:"Shared",bag:"Day bag",consumable:false,departureDay:false}],missing:[{name:"Water",quantity:2,reason:"Drink",category:"Food",inventoryId:""}]},{destination:"Gila",days:2,people:1,style:"hike",when:"Nov",extra:""});planSave(tripDraft);persist()');assert.equal(run('items[0].qty'),3)});
test('A full inventory swipe only reveals buttons; tapping an action changes stock once with Undo',()=>{const f=swipeFixture('gear','sw_1'),before=storage.get('fieldkit_inventory_v1');f.swipe(180);assert.equal(f.row.dataset.swipeOpen,'leading');assert.equal(f.leading.inert,false);assert.equal(f.trailing.inert,true);assert.equal(f.surface.inert,false);assert.equal(storage.get('fieldkit_inventory_v1'),before);assert.equal(run('entityContext'),null);const b=f.action('plus');gestureEvent('pointerdown',b);gestureEvent('click',b);assert.equal(run('items[0].qty'),4);assert.equal(f.surface.style.transform,'');assert.equal(f.surface.inert,false);run('undoAction()');assert.equal(run('items[0].qty'),3)});
test('Horizontal swipes keep their axis through diagonal drift and reverse directions cleanly',()=>{const f=swipeFixture('gear','sw_1');gestureEvent('pointerdown',f.content);const first=gestureEvent('pointermove',f.content,250,304);assert(first.prevented);gestureEvent('pointermove',f.content,252,355);assert.equal(f.surface.style.transform,'translateX(72px)');gestureEvent('pointermove',f.content,110,330);gestureEvent('pointerup',f.content,110,330);assert.equal(f.row.dataset.swipeOpen,'trailing');assert.equal(f.surface.style.transform,'translateX(-160px)');assert.equal(run('items[0].qty'),3);run('closeEntitySwipe()')});
test('Vertical scrolling and ambiguous diagonal movement never apply a swipe or edit',()=>{const f=swipeFixture('gear','sw_1');gestureEvent('pointerdown',f.content);const move=gestureEvent('pointermove',f.content,185,330);assert.equal(move.prevented,false);gestureEvent('pointerup',f.content,185,330);assert.equal(f.surface.style.transform,'');assert.equal(run('items[0].qty'),3);gestureEvent('pointerdown',f.content);gestureEvent('pointermove',f.content,200,318);gestureEvent('pointerup',f.content,200,318);assert.equal(f.row.dataset.swipeOpen,'');assert.equal(gestureEvent('click',f.content).stopped,true);assert.equal(run('quickEditing'),null)});
test('Pointer cancellation, lost capture, blur and resize restore surfaces and focusability',()=>{for(const signal of ['pointercancel','lostpointercapture','blur','resize']){const f=swipeFixture('kit','shared');gestureEvent('pointerdown',f.content);gestureEvent('pointermove',f.content,100,300);if(signal==='blur'||signal==='resize'){for(const fn of windowEvents[signal]||[])fn()}else gestureEvent(signal,signal==='lostpointercapture'?f.row:f.content);assert.equal(f.surface.style.transform,'',signal);assert.equal(f.surface.inert,false,signal);assert.equal(f.leading.inert,true,signal);assert.equal(f.trailing.inert,true,signal);assert.equal(f.row.classList.contains('swipe-tracking'),false,signal)}assert.equal(run('items[0].qty'),3)});
test('Only one row can stay open; a short swipe and browser-edge gestures do nothing',()=>{const a=swipeFixture('kit','shared'),b=swipeFixture('trip',run('plannerTripId'));a.swipe(-100);b.swipe(100);assert.equal(a.surface.style.transform,'');assert.equal(a.surface.inert,false);assert.equal(b.row.dataset.swipeOpen,'leading');run('closeEntitySwipe()');a.swipe(20);assert.equal(a.surface.style.transform,'');gestureEvent('pointerdown',a.content,10,300);gestureEvent('pointermove',a.content,110,300);gestureEvent('pointerup',a.content,110,300);assert.equal(a.surface.style.transform,'');assert.equal(run('entityContext'),null)});
test('The completing gesture click is blocked, while a fresh tap or keyboard action works immediately',()=>{const f=swipeFixture('gear','sw_1');f.swipe(100);assert(gestureEvent('click',f.content).stopped);assert.equal(run('quickEditing'),null);const b=f.action('plus');gestureEvent('pointerdown',b);gestureEvent('click',b);assert.equal(run('items[0].qty'),4);run('undoAction()');f.swipe(100);gestureEvent('click',f.action('plus'),180,300,201,{detail:0});assert.equal(run('items[0].qty'),4);run('undoAction()')});
test('Outside taps, Escape and scrolling close revealed actions without changing data',()=>{for(const signal of ['outside','escape','scroll']){const f=swipeFixture('gear','sw_1');f.swipe(-100);if(signal==='outside'){const outside=element('outside');outside.closest=()=>null;gestureEvent('pointerdown',outside)}else if(signal==='escape')gestureEvent('keydown',f.content,180,300,201,{key:'Escape',detail:0});else gestureEvent('scroll',f.content);assert.equal(f.surface.style.transform,'');assert.equal(f.surface.inert,false);assert.equal(run('items[0].qty'),3)}});
