test('A hold opens its menu once, while scrolling cancels a pending hold',()=>{const timer=context.setTimeout,clear=context.clearTimeout;let next=400,timers=new Map();context.setTimeout=(fn,ms)=>{const id=++next;if(ms===500)timers.set(id,fn);return id};context.clearTimeout=id=>timers.delete(id);const f=swipeFixture('gear','sw_1');gestureEvent('pointerdown',f.content);assert.equal(timers.size,1);gestureEvent('pointermove',f.content,184,330);assert.equal(timers.size,0);gestureEvent('pointerup',f.content,184,330);assert.equal(run('entityContext'),null);gestureEvent('pointerdown',f.content);const fn=[...timers.values()][0];fn();assert.equal(run('entityContext.kind'),'gear');assert.equal(gestureEvent('click',f.content).stopped,true);assert.equal(run('quickEditing'),null);run('entityClose()');context.setTimeout=timer;context.clearTimeout=clear});
test('Events from another pointer cannot finish or cancel the active swipe',()=>{const f=swipeFixture('kit','shared');gestureEvent('pointerdown',f.content,180,300,301);gestureEvent('pointermove',f.content,110,300,301);gestureEvent('pointercancel',f.content,110,300,999);assert.equal(f.surface.style.transform,'translateX(-70px)');gestureEvent('pointerup',f.content,110,300,999);assert.equal(f.row.dataset.swipeOpen,'');gestureEvent('pointerup',f.content,110,300,301);assert.equal(f.row.dataset.swipeOpen,'trailing');run('closeEntitySwipe()')});

function clickThrough(target,ancestors=[],detail=1){const e={target,detail,prevented:false,stopped:false,preventDefault(){this.prevented=true},stopImmediatePropagation(){this.stopped=true}};for(const {handler,capture}of eventOrder.click||[])if(capture){handler(e);if(e.stopped)return e}for(const node of [target,...ancestors]){node.onclick?.(e);if(e.stopped)return e}for(const {handler,capture}of eventOrder.click||[])if(!capture){handler(e);if(e.stopped)return e}return e}
test('An open row stays touchable and an inward swipe closes it from its own surface',()=>{const f=swipeFixture('gear','sw_1');f.swipe(50);assert.equal(f.row.dataset.swipeOpen,'leading');assert.equal(f.surface.inert,false);gestureEvent('pointerdown',f.content);gestureEvent('pointermove',f.content,135,302);gestureEvent('pointerup',f.content,135,302);assert.equal(f.row.dataset.swipeOpen,'');assert.equal(f.surface.style.transform,'');assert.equal(run('items[0].qty'),3)});
test('A second swipe can reverse a revealed row without an extra tap',()=>{const f=swipeFixture('gear','sw_1');f.swipe(50);f.swipe(-220);assert.equal(f.row.dataset.swipeOpen,'trailing');assert.equal(f.surface.style.transform,'translateX(-160px)');f.swipe(220);assert.equal(f.row.dataset.swipeOpen,'leading');assert.equal(run('items[0].qty'),3);run('closeEntitySwipe()')});
