test('Revealed actions replace surface tab stops and closing restores every original tabindex',()=>{const f=swipeFixture('gear','sw_1'),one=element('one'),two=element('two');one.setAttribute('tabindex','0');f.surface.querySelectorAll=()=>[one,two];f.swipe(50);assert.equal(one.getAttribute('tabindex'),'-1');assert.equal(two.getAttribute('tabindex'),'-1');assert.equal(f.surface.getAttribute('aria-hidden'),'true');assert.equal(f.leading.getAttribute('aria-hidden'),'false');run('closeEntitySwipe()');assert.equal(one.getAttribute('tabindex'),'0');assert.equal(two.getAttribute('tabindex'),null);assert.equal(f.surface.getAttribute('aria-hidden'),'false');assert.equal(f.leading.inert,true)});
