 const b={dataset:{planAcquire:'0',suggestionKey:run('window.plusKey')}};elements.get('plannerMissing').onclick({target:{closest:()=>b}});assert.equal(run('items.length'),1);assert.equal(run('items[0].qty'),2);assert.equal(run('items[0].status'),'stock');assert.equal(run('planCurrent().items[0].quantity'),2);assert.equal(run('planCurrent().items[0].packed'),0);assert(elements.get('planSubpanel').classList.contains('hidden'));assert.equal(run('planCurrent().missing.length'),1);const before=run('JSON.stringify(entitySnapshot())');assert.equal(run('planAcquire(0,window.plusKey)'),false);assert.equal(run('JSON.stringify(entitySnapshot())'),before);
