await atest('Planner consent blocks requests and payload excludes storage while including opted-in notes/photos',async()=>{
 for(let k=0;k<8;k++)await flush();let calls=0;context.fetch=async()=>{calls++;throw Error('Should not call')};elements.get('plannerAIConsent').checked=false;await run('plannerOptimize()');assert.equal(calls,0);assert(elements.get('plannerMessage').textContent.includes('consent'));
 run('items=[{id:"private",name:"Headlamp",place:"shared",status:"stock",qty:1,weightG:100,note:"my note",spot:"SECRET SHELF",photo:"data:image/jpeg;base64,eA=="}];tripDraft=planLocal({destination:"Gila",days:1,people:1,style:"hike",when:"Nov",extra:"kid"})');
 const payload=JSON.parse(run('JSON.stringify(plannerPayload(tripDraft,"lighter"))'));assert(!JSON.stringify(payload).includes('SECRET SHELF'));assert(JSON.stringify(payload).includes('my note'));assert(payload.some(p=>p.inlineData));delete context.fetch;
});
await atest('Planner requests structured JSON with header-only key, free allowlist and no quota retries',async()=>{
 context.AbortController=AbortController;const calls=[];const key='test_planner_key_123456789012345';storage.set('fieldkit_gemini_key_v1',key);
 context.fetch=async(url,opt)=>{calls.push([url,opt]);return {ok:true,json:async()=>({candidates:[{finishReason:'STOP',content:{parts:[{text:'{"name":"Gila","items":[],"missing":[],"assumptions":[]}'}]}}]})}};
 const result=await run('plannerRequest([{text:"test"}],PLAN_SCHEMA,PLAN_SYSTEM)');assert.equal(result.model,'gemini-3.8-flash');assert.equal(calls.length,1);const [url,opt]=calls[0],body=JSON.parse(opt.body);assert(!url.includes(key));assert.equal(opt.headers['x-goog-api-key'],key);assert.equal(body.generationConfig.responseMimeType,'application/json');assert(body.generationConfig.responseJsonSchema.properties.items);assert(!opt.body.includes(key));
 context.fetch=async()=>{calls.push(null);return {ok:false,status:429,json:async()=>({error:{message:'quota'}})}};await assert.rejects(run('plannerRequest([],PLAN_SCHEMA,PLAN_SYSTEM)'),/quota/);assert.equal(calls.length,2);
 context.fetch=async()=>({ok:true,json:async()=>({candidates:[{finishReason:'MAX_TOKENS',content:{parts:[{text:'{}'}]}}]})});await assert.rejects(run('plannerRequest([],PLAN_SCHEMA,PLAN_SYSTEM)'),/complete plan/);
 storage.delete('fieldkit_gemini_key_v1');delete context.fetch;
});

