await atest('Smart scan keeps trying when the model list fails and shows Google\'s own reason without the key',async()=>{
 for(let k=0;k<5;k++)await flush();const calls=[];const KEY='AQ.Ab8RN6Ltest-key_with.dots12345';storage.set('fieldkit_gemini_key_v1',KEY);storage.delete('fieldkit_gemini_model_v1');
 context.fetch=async(url,opt={})=>{calls.push([url,opt.headers?.['x-goog-api-key']]);const res=(status,body)=>({ok:status<300,status,json:async()=>body});
  if(url.includes('models?'))return res(403,{error:{message:'list blocked',status:'PERMISSION_DENIED'}});
  if(url.includes('gemini-3.8-flash:'))return res(404,{error:{message:'models/gemini-3.8-flash is not found',status:'NOT_FOUND'}});
  if(url.includes('gemini-3.5-flash:'))return res(200,{candidates:[{content:{parts:[{text:'OK'}]}}]});
  return res(500,{})};
 const el={textContent:''};assert.equal(await run('scanTestKey')(el),true);assert(el.textContent.includes('gemini-3.5-flash'));
 assert(calls.every(c=>c[1]===KEY&&!c[0].includes(KEY)));assert.equal(storage.get('fieldkit_gemini_model_v1'),'gemini-3.5-flash');
 context.fetch=async()=>({ok:false,status:403,json:async()=>({error:{message:'Method doesn\'t allow unregistered callers. Key '+KEY+' is not valid',status:'PERMISSION_DENIED'}})});
 storage.delete('fieldkit_gemini_model_v1');assert.equal(await run('scanTestKey')(el),false);
 assert(el.textContent.includes('Google said 403 PERMISSION_DENIED'));assert(el.textContent.includes('[key]'));assert(!el.textContent.includes(KEY));
 context.fetch=async()=>({ok:false,status:429,json:async()=>({error:{message:'quota',status:'RESOURCE_EXHAUSTED'}})});
 await assert.rejects(run('scanGemini')('data:image/jpeg;base64,eA==',10,10,KEY),/Free Gemini limit/);
 storage.delete('fieldkit_gemini_key_v1');storage.delete('fieldkit_gemini_model_v1');delete context.fetch});
